    def next_number(n):
        if n < 10:
            return n + n
        else:
            product = 1
            has_non_zero = False
            for digit in str(n):
                digit = int(digit)
                if digit != 0:
                    product *= digit
                    has_non_zero = True
            return n + product if has_non_zero else n

